<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
admin_required();
$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT id,name,price,image FROM products WHERE id=?');$q->execute([$id]);$product=$q->fetch();
