$url=product_public_url((int)$product['id']);$qr=qr_image_url($url,480);
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QR — <?=e($product['name'])?></title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;800&display=swap" rel="stylesheet"><style>body{margin:0;background:#15161a;color:#fff;font-family:Cairo,Tahoma,sans-serif}.wrap{width:min(650px,92%);margin:38px auto}.label{background:#fff;color:#161616;border-radius:16px;padding:28px;text-align:center;box-shadow:0 18px 60px #0008}.logo{width:72px;height:72px;border-radius:50%;object-fit:cover}.label h1{margin:10px 0 4px;font-size:27px}.label p{margin:4px 0;color:#444}.qr{width:min(100%,420px);margin:18px auto;display:block}.code{font-weight:800;letter-spacing:1px}.actions{display:flex;justify-content:center;gap:10px;margin-top:20px}.btn{padding:10px 15px;border-radius:8px;border:1px solid #ffd21c;background:#ffd21c;color:#171717;text-decoration:none;font-weight:800;cursor:pointer}.btn.alt{background:transparent;color:#fff}@media print{body{background:#fff}.wrap{width:100%;margin:0}.actions{display:none}.label{box-shadow:none}}</style></head><body><main class="wrap"><article class="label"><img class="logo" src="assets/images/autoland-logo.png" alt="AutoLand"><h1><?=e($product['name'])?></h1><p><?=$product['price']!==null?number_format((float)$product['price'],0,',',' ').' دج':'السعر عند الطلب'?></p><img class="qr" src="<?=e($qr)?>" alt="رمز QR لصفحة <?=e($product['name'])?>"><p class="code" dir="ltr">AL-P<?=str_pad((string)$product['id'],4,'0',STR_PAD_LEFT)?></p><p>امسح الرمز لفتح صفحة المنتج في متجر AutoLand.</p></article><div class="actions"><button class="btn" onclick="window.print()">طباعة الملصق</button><a class="btn alt" href="dashboard.php#store">العودة للوحة</a></div></main></body></html>
